 const channel=sourceSeal.originalPeerOriginFrontierSealChannel(cap),header=channel.header();assert.throws(()=>channel.submit({sha256:header.sha256,content:'Unread context cannot qualify.'}));let delivered='';for(let offset=0;offset<header.total_characters;){const part=channel.read({sha256:header.sha256,offset,length:Math.min(4096,header.total_characters-offset)});delivered+=part.text;offset+=part.length;}assert.equal(delivered,canonical(context));
 const contract=context.response_contract,output=canonical({protocol:contract.output_protocol,subject:context.subject,verdict:'Pass',reason:'SYNTHETIC independent full origin-layer preparation review, never business authority.',blockers:[],permitted_action:contract.permitted_action,mandatory_markers_sha256:context.subject.mandatory_markers_sha256,original_reservations_sha256:context.subject.original_reservations_sha256,original_units_sha256:context.subject.original_units_sha256});channel.submit({sha256:header.sha256,content:output});assert.throws(()=>channel.submit({sha256:header.sha256,content:output+' '}));
 const facts={protocol:'peer-owned-admitted-task-drain-v1',kind:binding.kind,admission_ref:binding.admission_ref,context_sha256:binding.context_sha256,native_id,thread_id:native_id,turn_id:'synthetic-final-source-turn',terminal_status:'completed',output,output_sha256:digest(output),group_absent:null,remote_domain_closed:false},token=domain.mintSyntheticDrain(f.ledger,facts),before=entireSql(f),child=Object.assign(Error('Actual SOURCE SQLite provider child'),{code:'ORIGIN_FRONTIER_SEAL_OUTPUT'}),aggregate=new AggregateError([child],'Actual SOURCE provider aggregate',{cause:child});
 for(const failure of [child,new TypeError('Actual SOURCE provider TypeError'),aggregate]){let hit=false;f.ledger.onQuery=({sql})=>{if(!hit&&sql.startsWith('SELECT')){hit=true;throw failure;}};try{await assert.rejects(sourceSeal.completeOriginalPeerOriginFrontierSeal(cap,token),e=>e===failure);}finally{f.ledger.onQuery=null;}assert.equal(hit,true);assert.equal(entireSql(f),before);}assert.strictEqual(aggregate.cause,child);assert.strictEqual(aggregate.errors[0],child);
