  const coldApi=sourceSeal.createPeerOriginFrontierSeal({ledger:cold,actor}),exact={operation_id:'source-archive-final-review',frontier_ref:frontier.frontier_ref,root_result_ref:frontier.root_result_ref},current=entireSql(f);assert.throws(()=>sourceSeal.prepareOriginalPeerOriginFrontierSeal(coldApi,exact),e=>e.code==='ORIGIN_FRONTIER_SEAL_ORIGINAL_CONTINUATION_REQUIRED');assert.throws(()=>sourceSeal.prepareOriginalPeerOriginFrontierSeal(coldApi,{...exact,operation_id:'source-new-op-same-logical-target'}));assert.equal(entireSql(f),current);
